function select(i){selected=i;picker.value=i;buttons.forEach((b,j)=>b.setAttribute('aria-pressed',String(j===i)));inspector.replaceChildren(el('p','arch-kicker',String(i+1).padStart(2,'0')+' / PROPOSED COMPONENT'),el('h4','',articles[i].querySelector('h4').textContent));for(const p of articles[i].querySelectorAll('p,small'))inspector.append(el(p.tagName.toLowerCase(),'',p.textContent));if(i<4)inspector.append(el('p','arch-boundary',steps[i].querySelector('small').textContent));if(cy){cy.nodes().unselect();cy.$id(ids[i]).select();}stage.dataset.selected=ids[i];}
function renderStep(index){path=index;buttons.forEach(b=>b.classList.remove('arch-traversed'));if(cy)cy.elements().removeClass('route-past route-current visited');if(path<0){select(0);progress.textContent='Ready at the browser. Advance or play the illustrative request. No traffic is sent.';stage.dataset.requestStep='0';return;}const visited=new Set([0]);route.slice(0,path+1).forEach(([edge,i],j)=>{visited.add(i);if(cy)cy.$id(edge).addClass(j===path?'route-current':'route-past');});visited.forEach(i=>{buttons[i].classList.add('arch-traversed');if(cy)cy.$id(ids[i]).addClass('visited');});const [,i,title,description]=route[path];select(i);progress.replaceChildren(el('strong','',String(path+1).padStart(2,'0')+' / '+route.length+' · '+title),el('span','',description));stage.dataset.requestStep=String(path+1);stage.dataset.activeEdge=route[path][0];}
