graph.addEventListener('keydown',event=>{if(!['+','=','-','0','ArrowRight','ArrowDown','ArrowLeft','ArrowUp','Home','End'].includes(event.key))return;event.preventDefault();if(event.key==='+'||event.key==='=')zoom(1.25);else if(event.key==='-')zoom(.8);else if(event.key==='0')fit();else if(event.key==='Home')select(0);else if(event.key==='End')select(8);else select((selected+(['ArrowRight','ArrowDown'].includes(event.key)?1:8))%9);});
source.querySelector('.a3-intro').before(stage);const research=el('details','arch-research');research.id='architecture-research';research.append(el('summary','','Complete Assignment 3 research — all nine components, methodology and references'));const retained=[];let sibling=stage.nextSibling;while(sibling){retained.push(sibling);sibling=sibling.nextSibling;}research.append(...retained);stage.after(research);
